mapper.select:
select e.customer_no, max(e.customer_name_snapshot) as customer_name, ifnull(sum(e.ead_amount),0) as ead_amount,
       ifnull(sum(e.el_downturn),0) as el_downturn_amount, max(e.risk_level) as risk_level
from corporate_risk_exposure e where  group by e.customer_no order by ead_amount desc limit #{limit}
